<?php
namespace App\Http\Controllers\API;
use App\Enums\LeaveRequestStatus; use App\Http\Controllers\Controller; use App\Http\Resources\LeaveRequestResource; use App\Http\Resources\LeaveTypeResource; use App\Models\LeaveRequest; use App\Models\LeaveType; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule;
class LeaveController extends Controller { public function types(Request $r) { $ownerId=$r->user()->id; foreach ([['Annual leave',20],['Sick leave',12],['Personal leave',5]] as [$name,$days]) { LeaveType::firstOrCreate(['owner_id'=>$ownerId,'name'=>$name],['days_per_year'=>$days,'is_active'=>true]); } $types=LeaveType::where('owner_id',$ownerId)->where('is_active',true)->orderBy('name')->get(); return LeaveTypeResource::collection($types); } public function index(Request $r) { $items=LeaveRequest::with(['staff','leaveType'])->where('owner_id',$r->user()->id)->latest()->paginate(20); return LeaveRequestResource::collection($items)->response(); } public function store(Request $r): JsonResponse { $d=$r->validate(['staff_id'=>['required','exists:staff,id'],'leave_type_id'=>['required','exists:leave_types,id'],'start_date'=>['required','date'],'end_date'=>['required','date','after_or_equal:start_date'],'reason'=>['nullable','string','max:1000']]); $r->user()->staff()->findOrFail($d['staff_id']); LeaveType::where('owner_id',$r->user()->id)->findOrFail($d['leave_type_id']); $item=LeaveRequest::create([...$d,'owner_id'=>$r->user()->id,'status'=>LeaveRequestStatus::Pending->value]); return response()->json(new LeaveRequestResource($item->load(['staff','leaveType'])),201); } public function updateStatus(Request $r, LeaveRequest $leaveRequest): JsonResponse { abort_unless($leaveRequest->owner_id === $r->user()->id,403); $d=$r->validate(['status'=>['required',Rule::enum(LeaveRequestStatus::class)]]); $leaveRequest->update([...$d,'reviewed_by'=>$r->user()->id]); return response()->json(new LeaveRequestResource($leaveRequest->load(['staff','leaveType']))); } }
